236	 * left or right toward the bearing, up when roughly on course and below the wanted speed, down when too fast. The
237	 * wanted speed falls as the target nears, so the ship arrives slowly.
238	 */
239	export async function sailTo(page: Page, target: { x: number; y: number }, options: SailOptions = {}): Promise<Readout> {
240	  const id = await selfId(page);
241	  const keys = new Keys(page);
242	  const deadline = Date.now() + (options.timeoutMs ?? 30_000);
243	  try {
244	    for (;;) {
245	      const ship = await readout(page, id);
246	      if (ship === undefined) throw new Error("own ship missing from the HUD");
247	      options.onReadout?.(ship);
248	      const dx = target.x - ship.x;
249	      const dy = target.y - ship.y;
250	      const distance = Math.hypot(dx, dy);
251	      if (options.within !== undefined && distance <= options.within) return ship;
252	      if (options.until !== undefined && (await options.until())) return ship;
253	      if (Date.now() > deadline) throw new Error(`did not reach ${target.x},${target.y} (at ${ship.x},${ship.y})`);
254	      const bearing = Math.round((Math.atan2(dy, dx) / (2 * Math.PI)) * HEADING_COUNT);
255	      const turn = ((((bearing - ship.heading) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
256	      await keys.set("ArrowRight", turn > 0);
257	      await keys.set("ArrowLeft", turn < 0);
258	      const wanted = Math.min(64, Math.max(14, (distance / TILE) * 10));
259	      const onCourse = Math.abs(turn) <= 4;
260	      await keys.set("ArrowUp", onCourse && ship.speed < wanted - 2);
261	      await keys.set("ArrowDown", ship.speed > wanted + 8);
262	      await page.waitForTimeout(30);
263	    }
264	  } finally {
265	    await keys.releaseAll();
266	  }
267	}
